--Total revenue generated by each seller
SELECT
    seller_id,
    SUM(price) AS total_revenue
FROM order_items
GROUP BY seller_id
ORDER BY total_revenue DESC
LIMIT 10;

--Number of items sold by each seller
select seller_id,count(*) as item_sold
from order_items
group by seller_id 
order by item_sold desc 
limit 10;

--Number of orders handled by each seller
select seller_id,count(distinct order_id) as order_handled
from order_items
group by seller_id 
order by order_handled desc
limit 10;

--revenue by seller state 
select s.seller_state,sum(oi.price) as total_revenue
from order_items oi 
join sellers s on oi.seller_id = s.seller_id 
group by s.seller_state 
order by total_revenue desc;

--Average review score for each seller
WITH seller_orders AS (
    SELECT DISTINCT seller_id, order_id
    FROM order_items
)
SELECT
    so.seller_id,
    ROUND(AVG(r.review_score), 2) AS average_review_score,
    COUNT(DISTINCT so.order_id) AS total_orders
FROM seller_orders so
JOIN order_reviews r
    ON so.order_id = r.order_id
GROUP BY so.seller_id
HAVING COUNT(DISTINCT so.order_id) >= 10
ORDER BY average_review_score DESC;


--rank seller by revenue
SELECT
    seller_id,
    SUM(price) AS total_revenue,
    RANK() OVER (
        ORDER BY SUM(price) DESC
    ) AS revenue_rank
FROM order_items
GROUP BY seller_id
ORDER BY revenue_rank
LIMIT 20;


-- Seller performance scorecard
WITH seller_revenue AS (
    SELECT
        seller_id,
        SUM(price) AS total_revenue,
        COUNT(DISTINCT order_id) AS total_orders
    FROM order_items
    GROUP BY seller_id
),
seller_orders AS (
    SELECT DISTINCT seller_id, order_id
    FROM order_items
),
seller_reviews AS (
    SELECT
        so.seller_id,
        AVG(r.review_score) AS avg_review_score
    FROM seller_orders so
    JOIN order_reviews r
        ON so.order_id = r.order_id
    GROUP BY so.seller_id
)
SELECT
    sr.seller_id,
    sr.total_revenue,
    sr.total_orders,
    ROUND(srev.avg_review_score, 2) AS avg_review_score,
    RANK() OVER (
        ORDER BY sr.total_revenue DESC
    ) AS revenue_rank
FROM seller_revenue sr
LEFT JOIN seller_reviews srev
    ON sr.seller_id = srev.seller_id
ORDER BY revenue_rank
LIMIT 20;



-- Seller performance categories
WITH seller_revenue AS (
    SELECT
        seller_id,
        SUM(price) AS total_revenue,
        COUNT(DISTINCT order_id) AS total_orders
    FROM order_items
    GROUP BY seller_id
),
seller_orders AS (
    SELECT DISTINCT seller_id, order_id
    FROM order_items
),
seller_reviews AS (
    SELECT
        so.seller_id,
        AVG(r.review_score) AS avg_review_score
    FROM seller_orders so
    JOIN order_reviews r
        ON so.order_id = r.order_id
    GROUP BY so.seller_id
)
SELECT
    sr.seller_id,
    sr.total_revenue,
    sr.total_orders,
    ROUND(srev.avg_review_score, 2) AS avg_review_score,
    CASE
        WHEN sr.total_revenue >= 100000
             AND srev.avg_review_score >= 4
            THEN 'Top Performer'
        WHEN sr.total_revenue >= 50000
            THEN 'Strong Performer'
        ELSE 'Developing Seller'
    END AS seller_category
FROM seller_revenue sr
LEFT JOIN seller_reviews srev
    ON sr.seller_id = srev.seller_id
ORDER BY sr.total_revenue DESC;


--advanced  seller scorecard
with seller_metrics as (
select oi.seller_id, sum(oi.price) as total_revenue, count(distinct oi.order_id) as total_order,
avg(r.review_score) as avg_review_score
from order_items oi 
left join order_reviews r on oi.order_id = r.order_id 
group by oi.seller_id
),
ranked_sellers as(
select seller_id, total_revenue,total_order,avg_review_score,rank() over(order by total_revenue desc) as revenue_rank
from seller_metrics 
)
select seller_id,round(total_revenue,2) as total_revenue,total_order,round(avg_review_score,2) as avg_review_score,
revenue_rank,
case
	when revenue_rank <= 10 and avg_review_score >= 4
	then 'Excellent'
	when revenue_rank <=100
	then 'Good'
	else 'Needs Improvement'
end as performance_category
from ranked_sellers 
order by revenue_rank;
